import {HAIL_SIZE_LABELS} from './hail-tools.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={Pioggia:'☂',Grandine:'◇',Neve:'❄',Vento:'≋',Allagamento:'≈','Cielo sereno':'☀'};
export function validPhotoHeader(bytes,mime){return mime==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:mime==='image/png'?bytes.length>=8&&[137,80,78,71,13,10,26,10].every((n,i)=>bytes[i]===n):mime==='image/webp'?bytes.length>=12&&String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP':false}
export function createQuickReport(ctx){const drafts=new Map();let generation=0;
 function grid(){return `<section class="card quick-report-panel"><h2>Segnala adesso</h2><p class="small">Zona: ${esc(ctx.get().place.name)} · Le osservazioni scadono dopo 2 ore.</p><div class="quick-report-grid">${Object.entries(icons).map(([kind,icon])=>`<button data-quick="${kind}"><span aria-hidden="true">${icon}</span><span>${kind}</span></button>`).join('')}</div><p class="small">Scegli un fenomeno: controlli zona e orario prima di pubblicare. La segnalazione resta visibile per 2 ore e non è un’allerta ufficiale.</p></section>`}
 function bind(){document.querySelectorAll('[data-quick]').forEach(button=>button.onclick=event=>{button.classList.add('report-selected');setTimeout(()=>button.classList.remove('report-selected'),650);if(ctx.quick){ctx.quick(button.dataset.quick,event.isTrusted);return}const {me,place}=ctx.get();if(!me)return ctx.login();const kind=button.dataset.quick,key=kind+'|'+place.name;const d=drafts.get(key)||{id:crypto.randomUUID(),text:'Osservo '+kind.toLowerCase()+' in zona.',photo:'',city:place.name.startsWith('Zona ')?'':place.name};drafts.set(key,d);++generation;let reading=false;
 const mapEligible=kind==='Grandine'&&Number.isFinite(place.latitude)&&Number.isFinite(place.longitude)&&Math.abs(place.latitude)<=85&&!place.name.startsWith('Zona ');ctx.modal('Segnala '+kind.toLowerCase(),`<p>Osservazione non verificata</p><label class="field"><span>Città o comune</span><input id="quick-city" required maxlength="80" value="${esc(d.city)}" placeholder="Es. Roma"></label><label class="field"><span>Cosa stai osservando?</span><textarea id="quick-description" required maxlength="1000">${esc(d.text)}</textarea></label>${kind==='Grandine'?`<div class="hail-report-fields"><label class="field"><span>Quando l’hai osservata?</span><select id="quick-hail-ago">${[[0,'Adesso'],[5,'Circa 5 minuti fa'],[15,'Circa 15 minuti fa'],[30,'Circa 30 minuti fa'],[60,'Circa un’ora fa']].map(([n,label])=>`<option value="${n}" ${n===(d.ago||0)?'selected':''}>${label}</option>`).join('')}</select></label><label class="field"><span>Dimensione approssimativa dei chicchi</span><select id="quick-hail-size">${Object.entries(HAIL_SIZE_LABELS).map(([id,label])=>`<option value="${id}" ${id===(d.size||'unknown')?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="small">Stima personale, non misurazione certificata. Se non puoi stimarla da un posto protetto, scegli “Non so stimarla”.</p>`:''}<label class="field"><span>Aggiungi o scatta una foto · JPG, PNG, WebP, massimo 1,5 MB</span><input id="quick-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label><img id="quick-preview" class="scanner-preview" alt="Anteprima della foto da pubblicare" ${d.photo?'src="'+d.photo+'"':'hidden'}><button type="button" id="quick-remove">Rimuovi foto</button><p id="quick-scan-status" class="scanner-status" role="status">${d.photo?'Foto conservata nella bozza.':'La verifica locale controlla formato e leggibilità, non il fenomeno.'}</p><p class="scanner-notice">L’analisi IA non certifica autenticità, luogo o dimensioni della grandine. Puoi pubblicare anche senza foto.</p>${me.vision?'<label class="scanner-consent"><input id="quick-analyze" type="checkbox"> Dopo la pubblicazione, invia foto e testo a OpenAI per un’analisi assistita.</label>':'<p class="small">Analisi IA non attiva: manca il collegamento OpenAI. La tua foto non sarà inviata a un servizio IA.</p>'}${mapEligible?`<label class="scanner-consent"><input id="quick-map" type="checkbox"> Mostra anche la zona selezionata di ${esc(place.name)} sulla mappa. La posizione viene arrotondata a circa un chilometro; non certifica il punto della grandinata.</label><p id="quick-map-status" class="small">Facoltativo. Se cambi comune, scegli prima la nuova località sulla mappa.</p>`:''}<p class="small">Contenuto pubblico · scadenza dopo 2 ore · nessuna notifica di emergenza.</p>`,async()=>{if(reading)return false;const text=$('#quick-description').value.trim();if(!text)return false;const analyze=$('#quick-analyze')?.checked&&d.photo;await ctx.api('posts',{id:d.id,text,city:d.city,kind,rapid:true,photo:d.photo,...(kind==='Grandine'?{hail:{size:d.size||'unknown',observed:Date.now()-(d.ago||0)*60000}}:{}),...(mapEligible&&$('#quick-map')?.checked&&d.city.trim()===place.name?{mapPoint:{latitude:place.latitude,longitude:place.longitude,consent:true}}:{})});drafts.delete(key);if(analyze){try{const r=await ctx.api('global/analyze',{id:d.id});ctx.toast('Pubblicata. Valutazione IA: '+r.summary)}catch(e){ctx.toast('Segnalazione pubblicata. '+e.message)}}else ctx.toast('Segnalazione pubblicata per 2 ore.');await ctx.loadFeed();return true});
 if($('#quick-hail-size'))$('#quick-hail-size').onchange=e=>d.size=e.target.value;if($('#quick-hail-ago'))$('#quick-hail-ago').onchange=e=>d.ago=Number(e.target.value);$('#confirm-dialog').textContent='Conferma e pubblica';$('#quick-description').oninput=e=>d.text=e.target.value;$('#quick-city').oninput=e=>{d.city=e.target.value;const m=$('#quick-map');if(m){const changed=d.city.trim()!==place.name;m.disabled=changed;if(changed)m.checked=false;$('#quick-map-status').textContent=changed?'Zona non aggiunta: il comune è cambiato. Seleziona prima la nuova località sulla mappa.':'Puoi aggiungere la zona selezionata alla mappa.'}};
 $('#quick-remove').onclick=()=>{generation++;d.photo='';$('#quick-photo').value='';$('#quick-preview').removeAttribute('src');$('#quick-preview').hidden=true;$('#quick-scan-status').textContent='Foto rimossa.';reading=false;$('#confirm-dialog').disabled=false};
 $('#quick-photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;const current=++generation;reading=true;$('#confirm-dialog').disabled=true;const out=$('#quick-scan-status'),preview=$('#quick-preview');out.textContent='Controllo della foto…';try{if(file.size>1500000||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Scegli una foto JPG, PNG o WebP fino a 1,5 MB.');const bytes=new Uint8Array(await file.arrayBuffer());if(!validPhotoHeader(bytes,file.type))throw Error('Il contenuto del file non corrisponde a una foto valida.');const bitmap=await createImageBitmap(file).catch(()=>{throw Error("La foto non è leggibile. Scegli un altro file.")});const width=bitmap.width,height=bitmap.height;bitmap.close();if(width<1||height<1||width*height>40000000)throw Error('Immagine troppo grande o non leggibile.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Lettura foto non riuscita.'));reader.readAsDataURL(file)});if(current!==generation||!out.isConnected||!$('#dialog').open)return;d.photo=data;preview.src=data;preview.hidden=false;out.textContent='Foto leggibile · '+width+' × '+height+' pixel. Fenomeno non verificato.'}catch(err){if(current===generation&&out.isConnected)out.textContent=err.message+' La foto precedente, se presente, è conservata.'}finally{if(current===generation){reading=false;if(out.isConnected)$('#confirm-dialog').disabled=false}}};
 })}
 $('#dialog')?.addEventListener('close',()=>{generation++});return {grid,bind};
}
